describe('numericValues', () => {
  it('coerces what an API actually sends, and never yields NaN', () => {
    expect(numericValues([1, '2', 3.5])).toEqual([1, 2, 3.5]);
    expect(numericValues(['x', null, undefined])).toEqual([0, 0, 0]);
    expect(numericValues(['1e3'])).toEqual([1000]);
    expect(numericValues(null)).toEqual([]);
    expect(numericValues({ a: 1 })).toEqual([]);
  });
});

describe('resolveChartProps', () => {
  it('defaults every field, so a bare chart still renders', () => {
    const spec = resolveChartProps({});
    expect(spec.values).toEqual([]);
    expect(spec.strokeWidth).toBeGreaterThan(0);
    expect(spec.colors.length).toBeGreaterThanOrEqual(0);
    expect(['bar', 'line', 'area', 'donut', 'pie']).toContain(spec.type);
  });
  it('accepts a known chartType and falls back to bar for an unknown one', () => {
    expect(resolveChartProps({ chartType: 'donut' }).type).toBe('donut');
    expect(resolveChartProps({ chartType: 'line' }).type).toBe('line');
    expect(resolveChartProps({ chartType: 'sunburst' }).type).toBe('bar');
    expect(resolveChartProps({ chartType: 42 }).type).toBe('bar');
  });
  it('sends a plotted chart\'s labels to the x axis, where a bar keeps them per point', () => {
    expect(resolveChartProps({ chartType: 'line', labels: ['Jan', 'Feb'] }).axisLabels).toEqual(['Jan', 'Feb']);
    expect(resolveChartProps({ chartType: 'bar', labels: ['Jan'] }).axisLabels).toEqual([]);
    expect(resolveChartProps({ chartType: 'bar', axisLabels: ['Q1'] }).axisLabels).toEqual(['Q1']);
  });
  it('shows a legend when labels exist unless the design says otherwise', () => {
    expect(resolveChartProps({ labels: ['a'] }).legend).toBe('right');
    expect(resolveChartProps({ labels: ['a'], legend: 'none' }).legend).toBe('none');
    expect(resolveChartProps({}).legend).toBe('none');
  });
  it('prefers BOUND values over the design values', () => {
    const spec = resolveChartProps({ values: [1, 2] }, [9, 8, 7]);
    expect(spec.values).toEqual([9, 8, 7]);
  });
  it('reads labels, grid and marker', () => {
    const spec = resolveChartProps({ labels: ['a', 'b'], gridLines: 3, marker: { index: 1, label: 'x' } });
    expect(spec.labels).toEqual(['a', 'b']);
    expect(spec.gridLines).toBe(3);
    expect(spec.marker).toEqual({ index: 1, label: 'x' });
  });
});

describe('plotBox', () => {
  const base = resolveChartProps({});
  it('reserves a band only when there is something to put in it', () => {
    const bare = plotBox({ ...base, axisLabels: [], marker: null }, 200);
    expect(bare.axisH).toBe(0);
    expect(bare.markerH).toBe(0);
    expect(bare.plotH).toBe(200);
  });
  it('takes the axis and marker bands out of the plot', () => {
    const full = plotBox({ ...base, axisLabels: ['Jan'], marker: { index: 0, label: 'x' } }, 200);
    expect(full.axisH).toBeGreaterThan(0);
    expect(full.markerH).toBeGreaterThan(0);
    expect(full.plotH).toBeLessThan(200);
  });
  it('never returns a negative plot for a box smaller than its bands', () => {
    expect(plotBox({ ...base, axisLabels: ['Jan'], marker: { index: 0, label: 'x' } }, 5).plotH).toBe(0);
  });
  it('leaves vertical breathing room, capped', () => {
    const tall = plotBox({ ...base, axisLabels: [] }, 4000);
    expect(tall.padY - tall.padX).toBeLessThanOrEqual(22);
    expect(tall.padY).toBeGreaterThan(tall.padX);
  });
});

describe('tint and segmentColors', () => {
  it('lightens towards white and clamps the amount', () => {
    expect(tint('rgba(0,0,0,1)', 0)).toBe('rgba(0,0,0,1)');
    expect(tint('rgba(0,0,0,1)', 1)).toBe('rgba(255,255,255,1)');
    expect(tint('rgba(0,0,0,1)', 5)).toBe(tint('rgba(0,0,0,1)', 1));
    expect(tint('rgba(0,0,0,1)', -5)).toBe(tint('rgba(0,0,0,1)', 0));
  });
  it('returns an unparseable colour unchanged rather than guessing', () => {
    expect(tint('not-a-colour', 0.5)).toBe('not-a-colour');
  });
  it('honours explicit colours and fills the rest by tinting', () => {
    const cols = segmentColors(3, ['red'], 'rgba(0,0,0,1)');
    expect(cols).toHaveLength(3);
    expect(cols[0]).toBe('red');
    expect(cols[1]).not.toBe(cols[2]);
  });
  it('does not tint a single segment', () => {
    expect(segmentColors(1, [], 'rgba(10,20,30,1)')).toEqual(['rgba(10,20,30,1)']);
  });
});

describe('several series share ONE y-scale', () => {
  it('keeps their relative heights instead of each filling the box', () => {
    const lo = linePoints([4, 5, 6], 100, 100, 0, 0, { min: 0, max: 10 });
    const hi = linePoints([0, 5, 10], 100, 100, 0, 0, { min: 0, max: 10 });
    expect(hi[0].y).toBeGreaterThan(lo[0].y); // 0 sits BELOW 4
    expect(hi[2].y).toBeLessThan(lo[2].y); // 10 sits ABOVE 6
  });

  it('without a domain each still scales to itself, as before', () => {
    const pts = linePoints([4, 5, 6], 100, 100, 0, 0);
    expect(pts[0].y).toBe(100);
    expect(pts[2].y).toBe(0);
  });
});

describe('linePoints', () => {
  it('spans the box edge to edge', () => {
    const pts = linePoints([0, 5, 10], 100, 50, 0, 0);
    expect(pts).toHaveLength(3);
    expect(pts[0]!.x).toBe(0);
    expect(pts[2]!.x).toBe(100);
  });
  it('puts a flat series in the middle instead of dividing by zero', () => {
    const pts = linePoints([7, 7, 7], 100, 50, 0, 0);
    expect(new Set(pts.map((p) => p.y)).size).toBe(1);
    expect(pts[0]!.y).toBe(25);
  });
  it('centres a single sample', () => {
    expect(linePoints([1], 100, 50, 0, 0)[0]!.x).toBe(50);
  });
  it('is empty for no samples', () => {
    expect(linePoints([], 100, 50, 0, 0)).toEqual([]);
  });
  it('maps the maximum to the top and the minimum to the bottom', () => {
    const pts = linePoints([0, 10], 100, 50, 0, 0);
    expect(pts[1]!.y).toBeLessThan(pts[0]!.y);
  });
});

describe('linePath and areaPath', () => {
  const pts = linePoints([1, 5, 2, 8], 100, 50, 0, 0);
  it('emits a move then straight segments', () => {
    const d = linePath(pts, false);
    expect(d.startsWith('M ')).toBe(true);
    expect(d).toContain(' L ');
    expect(d).not.toContain(' C ');
  });
  it('emits curves when smoothed, passing through every sample', () => {
    expect(linePath(pts, true)).toContain('C');
  });
  it('degenerates safely', () => {
    expect(linePath([], false)).toBe('');
    expect(linePath([{ x: 1, y: 2 }], false)).toBe('M 1 2');
  });
  it('closes an area back down to the baseline', () => {
    const d = areaPath(pts, 50, false);
    expect(d.startsWith('M ')).toBe(true);
    expect(d.trim().endsWith('Z')).toBe(true);
    expect(areaPath([], 50, false)).toBe('');
  });
});

describe('gridYs', () => {
  it('spreads n lines across the box', () => {
    const ys = gridYs(100, 5, 0);
    expect(ys).toHaveLength(5);
    expect(ys[0]).toBe(0);
    expect(ys[4]).toBe(100);
  });
  it('centres a single line and returns none for zero', () => {
    expect(gridYs(100, 1, 0)).toEqual([50]);
    expect(gridYs(100, 0, 0)).toEqual([]);
    expect(gridYs(100, -1, 0)).toEqual([]);
  });
});

